package main
import "fmt"
type Bird struct {
    Name          string
    Description   string
    Migratory     bool
    MigratoryFrom string
    MigratoryTo   string
}
func main() {
    redTailedHawk := Bird{
        Name:        "Red-tailed hawk",
        Description: "The red-tailed hawk is a bird of prey native to North America. It is easily identified by its reddish-brown tail and a distinctive high-pitched scream. It primarily feeds on small mammals and birds, and is known for its sharp eyesight and agility in flight.",
        Migratory:   true,
        MigratoryFrom: "Northern breeding grounds in Canada and Alaska",
        MigratoryTo: "Southern wintering grounds in the United States, Mexico, and Central America",
    }

    fmt.Printf("The %s is %s. It is %v that it is migratory, and it travels from %s to %s.\n", redTailedHawk.Name, redTailedHawk.Description, redTailedHawk.Migratory, redTailedHawk.MigratoryFrom, redTailedHawk.MigratoryTo)
}

